## Code Example
```javascript
function maxKBlocksWithCost(A, k, cost) {
  const n = A.length;
  const P = new Array(n+1).fill(0);
  for (let i = 1; i <= n; i++) P[i] = P[i-1] + A[i-1];
  const NEG = -1e15;
  const dp = Array.from({ length: n+1 }, () => new Array(k+1).fill(NEG));
  dp[0][0] = 0;
  const bestVal = new Array(k+1).fill(NEG);
  bestVal[0] = 0; // dp[0][0] - P[0]

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      const candidate = P[i] - cost + bestVal[t-1];
      dp[i][t] = Math.max(dp[i-1][t], candidate);
    }
    // update bestVal for next i
    for (let t = 1; t <= k; t++) {
      const val = dp[i][t-1] - P[i];
      if (val > bestVal[t]) bestVal[t] = val;
    }
  }
  return { dp, P };
}
```
